{
  "findings": [
    {
      "ref": "[D26]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default but can be turned off.",
      "stance": "risk",
      "quote": "Profiles for users under 16 default to private, so no one can see their boards except for them, and they can only have followers they've accepted through a unique link."
    },
    {
      "ref": "[D26]",
      "area": "money",
      "claim": "The app does not push in-app purchases, loot boxes, pay-to-win or subscription traps.",
      "stance": "neutral",
      "quote": "Pricing structure: Free"
    },
    {
      "ref": "[D26]",
      "area": "data",
      "claim": "The service collects user data and may share it with third parties for ads, but users can delete their data.",
      "stance": "risk",
      "quote": "Your privacy is important to us. We won't share this comment without your permission. If you chose to provide an email address, it will only be used to contact you about your comment. See our privacy policy."
    },
    {
      "ref": "[D26]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as profiles for users under 16 default to private and require acceptance of followers.",
      "stance": "mitigation",
      "quote": "Profiles for users under 16 default to private, so no one can see their boards except for them, and they can only have followers they've accepted through a unique link."
    },
    {
      "ref": "[D26]",
      "area": "content",
      "claim": "A parent reports that users may encounter mature or violent content, including self-harm and potentially harmful material, even though some is removed.",
      "stance": "risk",
      "quote": "concerns about what kids might stumble upon arose after a British teen died by suicide in 2017 after searching for items about depression and suicidal quotes and pinning images that involved self-harm."
    },
    {
      "ref": "[D26]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny and fines related to child safety and data practices.",
      "stance": "risk",
      "quote": "Pinterest constantly updates users' feed with items that relate to their activity on the site. So, in theory, if teens were to search for war information, for example, they might later see suggestions that contain battle photos or other violent images. That algorithmic capability may be problematic, according to an NBC News investigation that indicated the site was recommending photos and videos of young girls to users who'd sought similar content, which could inadvertently enable pedophiles to access, collect, and sexualize imagery of children."
    }
  ]
}
